UPDATE refresh_token SET revoke_reason = CASE WHEN revoked_at IS NULL THEN #{reason} ELSE revoke_reason END,
    revoked_at = COALESCE(revoked_at, #{revokedAt})
WHERE family_id = #{familyId}

UPDATE refresh_token
SET revoke_reason = #{reason}, revoked_at = #{revokedAt}
WHERE user_id = #{userId} AND revoked_at IS NULL

UPDATE refresh_token
SET revoked_at = #{revokedAt}, revoke_reason = #{reason}
WHERE id = #{id} AND user_id = #{userId} AND revoked_at IS NULL
